problems.solutionCode:
async function retryWithExponentialBackoff(asyncOperation, options = {}) {
  const maxRetries = options.maxRetries !== undefined ? options.maxRetries : 3;
  const baseDelayMs = options.baseDelayMs !== undefined ? options.baseDelayMs : 10;
  const maxDelayMs = options.maxDelayMs !== undefined ? options.maxDelayMs : 200;
  const isRetryable = options.isRetryable || (() => true);

  let attempt = 0;
  while (true) {
    try {
      return await asyncOperation();
    } catch (err) {
      if (!isRetryable(err) || attempt >= maxRetries) {
        throw err;
      }
      const delay = Math.min(maxDelayMs, baseDelayMs * Math.pow(2, attempt));
      await new Promise(resolve => setTimeout(resolve, delay));
      attempt++;
    }
  }
}

module.exports = { retryWithExponentialBackoff };

visibleTests.testCode:
let calls = 0;
const flakyTask = async () => {
  calls++;
  if (calls < 3) throw new Error('Network reset');
  return 'SUCCESS';
};

const result = await retryWithExponentialBackoff(flakyTask, { maxRetries: 3, baseDelayMs: 5 });
assert.strictEqual(result, 'SUCCESS');
assert.strictEqual(calls, 3);

let calls = 0;
const clientErrorTask = async () => {
  calls++;
  const err = new Error('Bad Request');
  err.statusCode = 400;
  throw err;
};

await assert.rejects(
  async () => {
    await retryWithExponentialBackoff(clientErrorTask, {
      maxRetries: 3,
      baseDelayMs: 5,
      isRetryable: (e) => e.statusCode >= 500
    });
  },
  (err) => {
    assert.strictEqual(err.statusCode, 400);
    return true;
  }
);
assert.strictEqual(calls, 1);

